const e = $('Clean Evidence').first().json;
const ai = e.ai || {};
const parent = $input.first().json;

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function onlyDigits(s) {
  return String(s).split('').filter(function (c) { return c >= '0' && c <= '9'; }).join('');
}
function list(a) {
  return (a && a.length) ? a.map(esc).join('<br>') : 'Not mentioned';
}

const phones = (ai.phone_numbers || []).map(function (p) {
  return onlyDigits(p).length === 10 ? p : p + ' (CHECK: not a 10-digit number, may be misheard)';
});
const amount = ai.amount_inr ? 'Rs ' + Number(ai.amount_inr).toLocaleString('en-IN') : 'Not mentioned';
const when = DateTime.now().setZone('Asia/Kolkata').toFormat('dd LLL yyyy, hh:mm a');

const css = [
  'body{font-family:Arial,sans-serif;color:#2b2b2b;margin:36px;}',
  'h1{color:#AA1A1A;margin:0;font-size:26px;}',
  '.sub{color:#777;margin:4px 0 20px;}',
  '.badge{display:inline-block;padding:7px 16px;border-radius:6px;color:#fff;font-weight:bold;background:#AA1A1A;}',
  'table{border-collapse:collapse;width:100%;margin-top:16px;}',
  'td{border:1px solid #ddd;padding:9px;vertical-align:top;}',
  'td.k{width:30%;background:#fcecec;font-weight:bold;}',
  '.quote{background:#f6f6f6;border-left:4px solid #AA1A1A;padding:12px;margin-top:6px;}',
  '.note{margin-top:24px;font-size:12px;color:#666;border-top:1px solid #ddd;padding-top:10px;}'
].join('');

const html = [
  '<!DOCTYPE html><html><head><meta charset="utf-8"><style>', css, '</style></head><body>',
  '<h1>Valid8 Evidence Report</h1>',
  '<div class="sub">Generated ', esc(when), ' (IST) for ', esc(parent.name || 'parent'), '</div>',
  '<div class="badge">Suspected scam: ', esc(ai.scam_type || 'unknown'), '</div>',
  '<table>',
  '<tr><td class="k">Person named by caller</td><td>', esc(ai.victim_named || 'Not mentioned'), '</td></tr>',
  '<tr><td class="k">Amount demanded</td><td>', esc(amount), '</td></tr>',
  '<tr><td class="k">Payment method</td><td>', esc(ai.payment_method || 'Not mentioned'), '</td></tr>',
  '<tr><td class="k">UPI IDs</td><td>', list(ai.upi_ids), '</td></tr>',
  '<tr><td class="k">Phone numbers</td><td>', list(phones), '</td></tr>',
  '<tr><td class="k">Deadline given</td><td>', esc(ai.deadline || 'Not mentioned'), '</td></tr>',
  '<tr><td class="k">Threats</td><td>', list(ai.threats), '</td></tr>',
  '<tr><td class="k">Uncertain details</td><td>', list(ai.uncertain), '</td></tr>',
  '<tr><td class="k">Summary</td><td>', esc(ai.summary || ''), '</td></tr>',
  '</table>',
  '<h3>Transcript (automatic, may contain errors)</h3>',
  '<div class="quote">', esc(e.transcript), '</div>',
  '<h3>What to do next</h3><ol>',
  '<li>Do not send money. Keep the original recording safe.</li>',
  '<li>If money was sent: call 1930 immediately or file at cybercrime.gov.in, and inform your bank with the UPI ID above.</li>',
  '<li>If no money was sent: report the number on Sanchar Saathi (Chakshu).</li>',
  '</ol>',
  '<div class="note">This report was generated automatically from a call recording. Details were extracted by AI and may contain errors. Please verify every number and UPI ID against the recording before filing.</div>',
  '</body></html>'
].join('');

return [{ json: { reportHtml: html, familyId: e.familyId, parentChatId: String(parent.chatId || '') } }];
